styles.css:
html,body{overflow-x:clip}
body{-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
figure.wp-block-image{margin-left:0;margin-right:0;margin-bottom:0}
.wp-block-image img{display:block;width:100%}
.br-section{padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80)}
.br-section--tight{padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--70)}
.br-hero{padding-top:var(--wp--preset--spacing--60)}
.br-page-head{padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--30)}
.br-split{gap:var(--wp--preset--spacing--70)}
.br-projects,.br-steps,.br-stats,.br-team,.br-meta{gap:var(--wp--preset--spacing--50)}
.br-projects+.br-projects{margin-top:var(--wp--preset--spacing--60)!important}
.br-head>*{max-width:820px}
.br-narrow{max-width:900px;margin-left:auto!important;margin-right:auto!important}
.br-center{text-align:center}
.br-label{font-size:.8rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--wp--preset--color--ocre);margin-bottom:.9rem}
.has-lin-color .br-label{color:var(--wp--preset--color--argile)}
.br-lead{font-size:var(--wp--preset--font-size--large);line-height:1.55;color:var(--wp--preset--color--pierre);max-width:34em}
.has-lin-color .br-lead{color:inherit;opacity:.85}
.br-muted{color:var(--wp--preset--color--pierre)}
.br-chips{gap:.5rem!important;margin-bottom:1.75rem}
.br-chip{margin:0!important;font-size:.82rem;font-weight:500;line-height:1;padding:.55rem 1rem;border-radius:999px;background:var(--wp--preset--color--argile);color:var(--wp--preset--color--nuit)}
.br-project .br-chips{margin:1.25rem 0 .75rem}
.br-project .br-chip{background:transparent;border:1px solid rgba(38,34,32,.22);padding:.45rem .85rem}
.br-project h3{font-size:var(--wp--preset--font-size--x-large);margin:0 0 .35rem}
.br-project h3 a{text-decoration:none;color:inherit}
.br-project h3 a::after{content:" ↗";color:var(--wp--preset--color--ocre)}
.br-project .wp-block-image{overflow:hidden;border-radius:32px}
.br-project .wp-block-image img{transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.br-project:hover .wp-block-image img{transform:scale(1.035)}
.wp-block-image.is-style-br-arrondi img{border-radius:32px}
.wp-block-image.is-style-br-galet img{border-radius:47% 53% 44% 56% / 56% 44% 56% 44%}
.br-statement{font-family:var(--wp--preset--font-family--bricolage);font-size:var(--wp--preset--font-size--x-large);line-height:1.3;letter-spacing:-.01em;font-weight:500}
.br-arrow a{display:inline-block;font-weight:600;text-decoration:none;color:var(--wp--preset--color--nuit);border-bottom:2px solid var(--wp--preset--color--ocre);padding-bottom:.15rem}
.br-arrow a::after{content:" →";display:inline-block;transition:transform .25s}
.br-arrow a:hover::after{transform:translateX(4px)}
.br-section-head{gap:1rem 2rem}
.br-section-head h2{margin:0}
.br-section-head .br-arrow{margin:0}
.br-num{font-family:var(--wp--preset--font-family--bricolage);font-weight:600;font-size:1rem;width:3rem;height:3rem;display:flex;align-items:center;justify-content:center;border-radius:47% 53% 44% 56% / 56% 44% 56% 44%;background:var(--wp--preset--color--ocre);color:var(--wp--preset--color--lin);margin-bottom:1.1rem}
.br-expertise{padding:1.75rem 0;border-top:1px solid rgba(38,34,32,.16)}
.br-expertise:last-child{border-bottom:1px solid rgba(38,34,32,.16)}
.br-expertise .br-num{float:left;margin:0 1.5rem 1rem 0}
.br-expertise h3{margin:0 0 .4rem}
.br-expertise p.br-muted{margin:0;overflow:hidden}
.br-quote{font-family:var(--wp--preset--font-family--bricolage);font-size:var(--wp--preset--font-size--x-large);line-height:1.3;font-weight:500;letter-spacing:-.01em}
.br-stat{font-family:var(--wp--preset--font-family--bricolage);font-size:clamp(3rem,6vw,4.5rem);font-weight:600;line-height:1;letter-spacing:-.03em;color:var(--wp--preset--color--olive);margin-bottom:.5rem}
.br-meta{border-top:1px solid rgba(38,34,32,.16);border-bottom:1px solid rgba(38,34,32,.16);padding:1.5rem 0}
.br-meta p{margin:0}
.br-meta .br-label{margin-bottom:.35rem}
.br-member h3{margin:1.5rem 0 .2rem}
.br-member p{margin:0}
.br-card{background:var(--wp--preset--color--blanc);border-radius:32px;padding:2.5rem}
.br-info+.br-info{margin-top:1.5rem}
.br-info p{margin:0}
.br-info .br-label{margin-bottom:.3rem}
.is-style-br-tirets{list-style:none;padding-left:0}
.is-style-br-tirets li{padding:.7rem 0 .7rem 2rem;border-bottom:1px solid rgba(38,34,32,.12);position:relative;margin:0}
.is-style-br-tirets li::before{content:"";position:absolute;left:0;top:1.15rem;width:.85rem;height:.6rem;background:var(--wp--preset--color--ocre-vif);border-radius:47% 53% 44% 56% / 56% 44% 56% 44%}
.br-cta{position:relative;overflow:hidden}
.br-cta::before,.br-cta::after{content:"";position:absolute;border-radius:47% 53% 44% 56% / 56% 44% 56% 44%;pointer-events:none}
.br-cta::before{width:420px;height:300px;right:-90px;top:-80px;background:var(--wp--preset--color--ocre-vif);opacity:.9;transform:rotate(-18deg)}
.br-cta::after{width:260px;height:190px;right:180px;bottom:-110px;background:var(--wp--preset--color--argile);opacity:.35;transform:rotate(12deg)}
.br-cta-inner{position:relative;z-index:1}
.br-cta-inner>*{max-width:680px}
.br-cta h2{font-size:var(--wp--preset--font-size--huge);color:inherit}
.br-cta .wp-block-button__link:hover{background:var(--wp--preset--color--ocre)!important;color:var(--wp--preset--color--lin)!important}
.br-posts .wp-block-post-template{gap:var(--wp--preset--spacing--50)}
.br-post-card{background:var(--wp--preset--color--blanc);border-radius:28px;overflow:hidden;height:100%}
.br-post-card .wp-block-post-featured-image{margin:0}
.br-post-card:not(:has(.wp-block-post-featured-image))::before{content:"";display:block;aspect-ratio:4/3;background:radial-gradient(ellipse 40% 34% at 62% 48%,var(--br-shape) 98%,transparent 100%),radial-gradient(ellipse 22% 18% at 36% 62%,var(--br-shape2) 98%,transparent 100%),var(--br-bg)}
.wp-block-post-template>li:nth-child(3n+1) .br-post-card{--br-bg:#e3d2bd;--br-shape:#c4622d;--br-shape2:#4b5434}
.wp-block-post-template>li:nth-child(3n+2) .br-post-card{--br-bg:#dfe2cd;--br-shape:#4b5434;--br-shape2:#f4ede3}
.wp-block-post-template>li:nth-child(3n) .br-post-card{--br-bg:#4b5434;--br-shape:#e3d2bd;--br-shape2:#c4622d}
.br-post-body{padding:1.5rem 1.75rem 2rem}
.br-post-body>*{margin:0}
.br-post-body .wp-block-post-title{font-size:1.4rem;line-height:1.25;margin:.5rem 0 1rem}
.br-post-body .wp-block-post-title a{text-decoration:none;color:inherit}
.br-post-body .wp-block-post-title a:hover{color:var(--wp--preset--color--ocre)}
.br-post-body .wp-block-post-terms a{color:inherit;text-decoration:none;font-size:.9rem}
.br-header{padding-top:1.4rem;padding-bottom:1.4rem}
.br-header-inner{max-width:var(--wp--style--global--content-size);margin-left:auto!important;margin-right:auto!important;width:100%}
.br-logo{font-family:var(--wp--preset--font-family--bricolage);font-size:1.9rem;font-weight:700;letter-spacing:-.04em;line-height:1;margin:0}
.br-logo a,.br-logo{text-decoration:none;color:inherit;position:relative}
.br-logo a::after,.wp-block-site-title.br-logo a::after{content:"";display:inline-block;width:.42em;height:.3em;margin-left:.08em;background:var(--wp--preset--color--ocre-vif);border-radius:47% 53% 44% 56% / 56% 44% 56% 44%;transform:rotate(-14deg)}
.br-nav{gap:1.5rem;font-size:.95rem}
.br-nav a{text-decoration:none}
.br-nav a:hover{color:var(--wp--preset--color--ocre)}
.wp-block-navigation__responsive-container.is-menu-open{background:var(--wp--preset--color--lin)!important;padding:2rem}
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content{font-family:var(--wp--preset--font-family--bricolage);font-size:2.2rem;font-weight:600;gap:1rem}
.br-footer{padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--40)}
.br-footer a{color:inherit}
.br-footer-mail{font-family:var(--wp--preset--font-family--bricolage);font-size:clamp(1.8rem,4.6vw,3.6rem);font-weight:600;letter-spacing:-.03em;line-height:1.05;margin-bottom:var(--wp--preset--spacing--60)!important;word-break:break-word}
.br-footer-mail a{text-decoration:none;background-image:linear-gradient(var(--wp--preset--color--ocre-vif),var(--wp--preset--color--ocre-vif));background-size:100% 4px;background-position:0 100%;background-repeat:no-repeat;padding-bottom:.1em}
.br-footer-mail a:hover{color:var(--wp--preset--color--argile)}
.br-footer-text{opacity:.75;max-width:26em}
.br-footer .br-label{color:var(--wp--preset--color--argile)}
.br-footer-bottom{border-top:1px solid rgba(244,237,227,.18);padding-top:1.5rem;margin-top:var(--wp--preset--spacing--60)!important;font-size:.9rem;opacity:.75}
.br-footer-bottom p{margin:0}
.wp-block-button.is-style-outline .wp-block-button__link{background:transparent;color:var(--wp--preset--color--nuit);border:1.5px solid currentColor;padding:calc(1rem - 1.5px) calc(1.8rem - 1.5px)}
.wp-block-button.is-style-outline .wp-block-button__link:hover{background:var(--wp--preset--color--nuit);color:var(--wp--preset--color--lin);border-color:var(--wp--preset--color--nuit)}
.wp-block-details{border-bottom:1px solid rgba(38,34,32,.16);padding:1.2rem 0}
.wp-block-details summary{font-weight:600;cursor:pointer}
.br-article .wp-block-post-content>h2{font-size:var(--wp--preset--font-size--x-large);margin-top:2.5rem}
:where(.wp-site-blocks) :focus-visible{outline:2px solid var(--wp--preset--color--ocre);outline-offset:3px}
@media (max-width:781px){
.br-section{padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)}
.br-split{gap:var(--wp--preset--spacing--50)}
.br-projects+.br-projects{margin-top:var(--wp--preset--spacing--50)!important}
.br-hero .wp-block-column:last-child{max-width:72%;margin:0 auto}
.br-intro{padding-top:var(--wp--preset--spacing--40)}
.br-cta::before{width:240px;height:170px;right:-80px;top:-60px}
.br-cta::after{display:none}
.br-stats{display:grid!important;grid-template-columns:1fr 1fr;gap:1.75rem}
.br-meta{display:grid!important;grid-template-columns:1fr 1fr;gap:1.25rem}
.wp-block-image.is-style-br-arrondi img,.br-project .wp-block-image{border-radius:22px}
.br-card{padding:2rem 1.5rem}
.br-logo{font-size:1.6rem}
}
.br-logo-sub{font-weight:500;color:var(--wp--preset--color--pierre)}
.br-footer .br-logo-sub{color:var(--wp--preset--color--argile)}
.br-logo a::after,.wp-block-site-title.br-logo a::after{order:2}
.br-breadcrumb{font-size:.875rem;color:var(--wp--preset--color--pierre);margin-bottom:1.5rem}
.br-breadcrumb a{color:inherit}
.br-intro{font-size:var(--wp--preset--font-size--large);line-height:1.55;font-weight:500}
.br-table table{border-collapse:collapse;width:100%;font-size:.98rem}
.br-table th{text-align:left;font-weight:600;font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;color:var(--wp--preset--color--pierre);border-bottom:2px solid var(--wp--preset--color--nuit);padding:.75rem .9rem .75rem 0}
.br-table td{border-bottom:1px solid rgba(38,34,32,.16);padding:1rem .9rem 1rem 0;vertical-align:top}
.br-table td:first-child{font-weight:600}
.br-table a{color:var(--wp--preset--color--nuit);text-decoration-color:var(--wp--preset--color--ocre-vif);text-underline-offset:3px}
.br-planning td:last-child a{display:inline-block;font-weight:600;font-size:.9rem;text-decoration:none;border:1.5px solid var(--wp--preset--color--nuit);border-radius:999px;padding:.35rem 1rem}
.br-planning td:last-child a:hover{background:var(--wp--preset--color--nuit);color:var(--wp--preset--color--lin)}
.br-planning td:last-child{text-align:right}
.br-style+.br-style{margin-top:0}
.br-style h3{font-size:var(--wp--preset--font-size--x-large);scroll-margin-top:2rem}
.br-price{display:flex;flex-direction:column}
.br-price .wp-block-buttons{margin-top:auto;padding-top:1rem}
.br-price h3{margin:0}
.br-booking{padding:2.5rem}
.br-booking .br-chips{margin:1.5rem 0 0}
.br-steps-list li{margin:.5rem 0}
.br-sticky{display:none}
.br-card .br-stat{color:var(--wp--preset--color--olive)}
.br-section .br-card{height:100%}
.br-article .br-label a{color:inherit;text-decoration:none}
.br-skip:focus{position:fixed;top:1rem;left:1rem;z-index:100;background:var(--wp--preset--color--nuit);color:var(--wp--preset--color--lin);padding:.75rem 1rem;border-radius:8px}
@media (max-width:781px){
.br-sticky{display:block;position:fixed;left:0;right:0;bottom:0;z-index:50;padding:.75rem 1rem calc(.75rem + env(safe-area-inset-bottom));background:var(--wp--preset--color--lin);box-shadow:0 -10px 30px -12px rgba(38,34,32,.35)}
.br-sticky .wp-block-buttons,.br-sticky .wp-block-button,.br-sticky .wp-block-button__link{width:100%;justify-content:center;text-align:center}
.br-footer{padding-bottom:6rem}
.br-table{overflow-x:auto}
.br-table table{font-size:.92rem}
.br-planning td:last-child a{padding:.3rem .75rem}
.br-nav{gap:1rem}
}

.br-header-cta{margin:0}
.br-header-cta .wp-block-button__link{padding:.6rem 1.3rem;font-size:.95rem}
.br-header-right{gap:1.5rem}
@media (max-width:781px){.br-header-cta{display:none}}
